// ❌ Fragment holding its view past onDestroyView
class ProfileFragment : Fragment(R.layout.fragment_profile) {
  private var binding: ProfileBinding? = null

  override fun onViewCreated(view: View, saved: Bundle?) {
    binding = ProfileBinding.bind(view)
    viewLifecycleOwner.lifecycleScope.launch {    // ✅ dies with the view, not the fragment
      viewLifecycleOwner.repeatOnLifecycle(Lifecycle.State.STARTED) {
        vm.state.collect { render(it) }
      }
    }
  }

  override fun onDestroyView() {
    super.onDestroyView()
    binding = null                                // ✅ without this the whole tree is retained
  }
}

