class MyApp : Application() {
  override fun onCreate() {
    super.onCreate()
    reportLastExit()
  }

  private fun reportLastExit() {
    if (Build.VERSION.SDK_INT < Build.VERSION_CODES.R) return
    val am = getSystemService(ActivityManager::class.java)
    val last = am.getHistoricalProcessExitReasons(packageName, 0, 1).firstOrNull() ?: return

    Crashlytics.setCustomKey("last_exit_reason", last.reason)      // REASON_LOW_MEMORY, ...
    Crashlytics.setCustomKey("last_exit_importance", last.importance)
    Crashlytics.setCustomKey("last_exit_pss_kb", last.pss)

    if (last.reason == ApplicationExitInfo.REASON_ANR) {
      last.traceInputStream?.bufferedReader()?.use { Crashlytics.log(it.readText()) }
    }
  }
}

